        'important_terms' => [
            ['term' => 'Incentive Salience', 'definition' => 'A cognitive and motivational process wherein environmental stimuli associated with drug use acquire exaggerated motivational magnet properties, driving cue-induced craving.'],
            ['term' => 'Extended Amygdala', 'definition' => 'A limbic network (bed nucleus of the stria terminalis, central amygdala) that mediates the negative emotional state of drug withdrawal via CRF and dynorphin.'],
            ['term' => 'Opponent-Process Theory', 'definition' => 'A psychological model stating that drug-induced euphoria triggers compensatory anti-reward biological mechanisms that produce dysphoria upon drug clearance.'],
            ['term' => 'Sensitization', 'definition' => 'A progressive increase in drug effect or craving following repeated intermittent exposure to the same drug dose, mediated by dopaminergic neuroplasticity.']
